'37.72':[['(a) 8000 kg','(b) 12 000 kg','(c) 16 000 kg','(d) 25 000 kg','(e) 33 300 kg'],['(a) 8000 kg','(b) 12,000 kg','(c) 16,000 kg','(d) 25,000 kg','(e) 33,300 kg']],
